import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'aevko-trace',
  standalone: true,
  template: '<div role="list" [attr.aria-label]="label()"><ng-content /></div>',
  styleUrl: './trace.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoTrace {
  readonly label = input('Event trace');
}

@Component({
  selector: 'aevko-trace-item',
  standalone: true,
  template:
    '<div class="item"><span class="marker" aria-hidden="true"></span><div><div class="header"><ng-content select="[aevkoTraceTitle]" /><ng-content select="[aevkoTraceTime]" /></div><div class="detail"><ng-content /></div></div></div>',
  styleUrl: './trace-item.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'listitem', '[attr.data-state]': 'state()' },
})
export class AevkoTraceItem {
  readonly state = input<'complete' | 'running' | 'error' | 'pending'>('complete');
}

:host {
  display: block;
}
div {
  list-style: none;
  margin: 0;
  padding: 0;
}

:host {
  display: block;
}
.item {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: auto 1fr;
  min-height: 4rem;
  position: relative;
}
.item::before {
  background: var(--aevko-border, #e4e4e7);
  content: '';
  inset-block: 0.75rem -0.25rem;
  inset-inline-start: 0.3rem;
  position: absolute;
  width: 1px;
}
.marker {
  background: var(--aevko-muted, #71717a);
  height: 0.65rem;
  margin-top: 0.4rem;
  position: relative;
  width: 0.65rem;
  z-index: 1;
}
:host([data-state='complete']) .marker,
:host([data-state='running']) .marker {
  background: var(--aevko-foreground, #09090b);
}
:host([data-state='error']) .marker {
  background: var(--aevko-danger, #3f3f3f);
}
:host([data-state='running']) .marker {
  animation: aevko-trace-pulse 1.4s ease-in-out infinite;
}
.header {
  display: flex;
  gap: 1rem;
  justify-content: space-between;
}
.detail {
  color: var(--aevko-muted, #71717a);
  margin-top: 0.25rem;
}
@keyframes aevko-trace-pulse {
  50% {
    opacity: 0.4;
  }
}
@media (prefers-reduced-motion: reduce) {
  :host([data-state='running']) .marker {
    animation: none;
  }
}
